import os
import stripe
from langchain_core.tools import tool
stripe.api_key = os.environ['STRIPE_API_KEY']

@tool
def pay_freight_invoice(invoice_id: str, amount_cents: int, carrier_account_id: str) -> str:
    t = stripe.Transfer.create(amount=amount_cents, currency='usd', destination=carrier_account_id, transfer_group=invoice_id, metadata={'invoice_id': invoice_id}, idempotency_key=f'freight-{invoice_id}')
    # Ensure the carrier account has the capabilities needed to receive future transfers and card payments
    stripe.Account.modify(
        carrier_account_id,
        capabilities={
            'transfers': {'requested': True},
            'card_payments': {'requested': True},
        },
    )
    return f'Paid invoice {invoice_id}: transfer {t.id} for {amount_cents} cents'
